package com.gerenciadorrural.modules.inventory.application;
import com.gerenciadorrural.modules.inventory.domain.*; import com.gerenciadorrural.shared.tenancy.*; import org.springframework.stereotype.Service; import java.math.*; import java.time.*; import java.util.*; import static com.gerenciadorrural.modules.inventory.domain.InventoryModels.*;
@Service public class InventoryService {private final TenantTransactionExecutor tx;private final InventoryRepository repo;private final Clock clock;private static final Set<String> WRITE=Set.of("OWNER","ADMIN","MANAGER"),MOVE=Set.of("OWNER","ADMIN","MANAGER","OPERATOR");public InventoryService(TenantTransactionExecutor tx,InventoryRepository repo,Clock clock){this.tx=tx;this.repo=repo;this.clock=clock;}
public Product createProduct(TenantContext c,UUID id,String name,String code,String category,Unit unit){write(c);Product p=new Product(id==null?UUID.randomUUID():id,text(name,160,false),nullable(code,80),nullable(category,120),req(unit),Status.ACTIVE,0,null,null);return tx.execute(c,()->repo.insertProduct(c.tenantId(),p));}public Location createLocation(TenantContext c,UUID id,String name,String code){write(c);Location l=new Location(id==null?UUID.randomUUID():id,text(name,160,false),nullable(code,80),Status.ACTIVE,0,null,null);return tx.execute(c,()->repo.insertLocation(c.tenantId(),c.farmId(),l));}public Product product(TenantContext c,UUID id){return tx.execute(c,()->repo.product(c.tenantId(),id,false).orElseThrow(NotFound::new));}public Location location(TenantContext c,UUID id){return tx.execute(c,()->repo.location(c.tenantId(),c.farmId(),id,false).orElseThrow(LocationNotFound::new));}
public Product patchProduct(TenantContext c,UUID id,Long version,String name,boolean hasName,String code,boolean hasCode,String category,boolean hasCategory,Status status,boolean hasStatus){write(c);if(version==null||version<0||(hasName&&name==null)||(hasStatus&&status==null))throw new Invalid();return tx.execute(c,()->{Product x=repo.product(c.tenantId(),id,true).orElseThrow(NotFound::new);Product n=new Product(x.id(),hasName?text(name,160,false):x.name(),hasCode?nullable(code,80):x.code(),hasCategory?nullable(category,120):x.category(),x.baseUnit(),hasStatus?status:x.status(),x.version(),x.createdAt(),x.updatedAt());if(n.status()==Status.INACTIVE&&x.status()!=Status.INACTIVE&&repo.productTotal(c.tenantId(),id).signum()!=0)throw new ProductInUse();if(same(x,n))return x;return repo.updateProduct(c.tenantId(),n,version);});}public Location patchLocation(TenantContext c,UUID id,Long version,String name,boolean hasName,String code,boolean hasCode,Status status,boolean hasStatus){write(c);if(version==null||version<0||(hasName&&name==null)||(hasStatus&&status==null))throw new Invalid();return tx.execute(c,()->{Location x=repo.location(c.tenantId(),c.farmId(),id,true).orElseThrow(LocationNotFound::new);Location n=new Location(x.id(),hasName?text(name,160,false):x.name(),hasCode?nullable(code,80):x.code(),hasStatus?status:x.status(),x.version(),x.createdAt(),x.updatedAt());if(n.status()==Status.INACTIVE&&x.status()!=Status.INACTIVE&&repo.locationTotal(c.tenantId(),c.farmId(),id).signum()!=0)throw new LocationNotEmpty();if(same(x,n))return x;return repo.updateLocation(c.tenantId(),c.farmId(),n,version);});}
public Movement move(TenantContext c,UUID op,Type type,UUID product,UUID source,UUID destination,BigDecimal quantity,LocalDate date,String notes){if(!MOVE.contains(c.role()))throw new Forbidden();Valid v=valid(op,type,product,source,destination,quantity,date,notes);String canonical=v.type+"|"+v.product+"|"+v.source+"|"+v.destination+"|"+v.quantity.stripTrailingZeros().toPlainString()+"|"+v.date+"|"+(v.notes==null?"":v.notes);return tx.execute(c,()->{Optional<String> old=repo.operation(c.tenantId(),c.farmId(),op);if(old.isPresent()){if(!old.get().equals(canonical))throw new IdempotencyConflict();return repo.movementByOperation(c.tenantId(),c.farmId(),op).orElseThrow(Conflict::new);}Product p=repo.product(c.tenantId(),product,true).orElseThrow(NotFound::new);if(p.status()!=Status.ACTIVE)throw new Conflict();List<UUID> locations=new ArrayList<>();if(source!=null)locations.add(source);if(destination!=null)locations.add(destination);locations.stream().sorted(Comparator.comparing(UUID::toString)).forEach(location->{Location item=repo.location(c.tenantId(),c.farmId(),location,true).orElseThrow(LocationNotFound::new);if(item.status()!=Status.ACTIVE)throw new Conflict();});repo.saveOperation(c.tenantId(),c.farmId(),op,canonical);Map<UUID,BigDecimal> deltas=new HashMap<>();if(source!=null)deltas.put(source,v.quantity.negate());if(destination!=null)deltas.put(destination,v.quantity);Map<UUID,BigDecimal> after=new HashMap<>();deltas.keySet().stream().sorted(Comparator.comparing(UUID::toString)).forEach(location->after.put(location,repo.changeBalance(c.tenantId(),c.farmId(),location,product,deltas.get(location))));Location s=source==null?null:repo.location(c.tenantId(),c.farmId(),source,false).orElseThrow(LocationNotFound::new),d=destination==null?null:repo.location(c.tenantId(),c.farmId(),destination,false).orElseThrow(LocationNotFound::new);Movement m=new Movement(UUID.randomUUID(),op,type,product,p.name(),p.baseUnit(),source,s==null?null:s.name(),destination,d==null?null:d.name(),v.quantity,source==null?null:after.get(source),destination==null?null:after.get(destination),date,c.userId(),v.notes,Instant.now(clock));repo.movement(c.tenantId(),c.farmId(),m);return m;});}
public List<Product> products(TenantContext c){return tx.execute(c,()->repo.products(c.tenantId()));}public List<Location> locations(TenantContext c){return tx.execute(c,()->repo.locations(c.tenantId(),c.farmId()));}public Page<Balance> stock(TenantContext c,UUID l,UUID p,String q,boolean pos,int page,int size){return tx.execute(c,()->page(repo.balances(c.tenantId(),c.farmId(),l,p,q,pos,size,(long)page*size),page,size,repo.balanceCount(c.tenantId(),c.farmId(),l,p,q,pos)));}public Page<Movement> history(TenantContext c,Type type,UUID p,UUID l,LocalDate from,LocalDate to,int page,int size){return tx.execute(c,()->page(repo.movements(c.tenantId(),c.farmId(),type,p,l,from,to,size,(long)page*size),page,size,repo.movementCount(c.tenantId(),c.farmId(),type,p,l,from,to)));}public Movement movement(TenantContext c,UUID id){return tx.execute(c,()->repo.movement(c.tenantId(),c.farmId(),id).orElseThrow(MovementNotFound::new));}
private Valid valid(UUID op,Type t,UUID p,UUID s,UUID d,BigDecimal q,LocalDate day,String n){if(op==null||t==null||p==null||q==null||day==null||day.isAfter(LocalDate.now(clock))||q.signum()<=0||q.scale()>6||q.precision()>19)throw new Invalid();boolean in=t==Type.RECEIPT||t==Type.ADJUSTMENT_IN,out=t==Type.ISSUE||t==Type.ADJUSTMENT_OUT;if((in&&(s!=null||d==null))||(out&&(s==null||d!=null))||(t==Type.TRANSFER&&(s==null||d==null||s.equals(d))))throw new Invalid();return new Valid(op,t,p,s,d,q,day,nullable(n,1000));}private record Valid(UUID op,Type type,UUID product,UUID source,UUID destination,BigDecimal quantity,LocalDate date,String notes){}private static <T> Page<T> page(List<T>x,int p,int s,long total){return new Page<>(x,p,s,total,Math.toIntExact((total+s-1)/s));}public record Page<T>(List<T> items,int page,int size,long totalElements,int totalPages){}private static Unit req(Unit x){if(x==null)throw new Invalid();return x;}private static String text(String x,int n,boolean nullable){String y=nullable?nullable(x,n):x==null?null:x.strip();if(y==null||y.isBlank()||y.indexOf('\0')>=0||y.codePointCount(0,y.length())>n)throw new Invalid();return y;}private static String nullable(String x,int n){if(x==null)return null;String y=x.strip();if(y.isEmpty())return null;if(y.indexOf('\0')>=0||y.codePointCount(0,y.length())>n)throw new Invalid();return y;}private static void write(TenantContext c){if(!WRITE.contains(c.role()))throw new Forbidden();}private static boolean same(Product a,Product b){return a.name().equals(b.name())&&Objects.equals(a.code(),b.code())&&Objects.equals(a.category(),b.category())&&a.status()==b.status();}private static boolean same(Location a,Location b){return a.name().equals(b.name())&&Objects.equals(a.code(),b.code())&&a.status()==b.status();}
public static class Invalid extends RuntimeException{}public static class Forbidden extends RuntimeException{}public static class NotFound extends RuntimeException{}public static class LocationNotFound extends RuntimeException{}public static class MovementNotFound extends RuntimeException{}public static class Conflict extends RuntimeException{}public static class ProductInUse extends RuntimeException{}public static class LocationNotEmpty extends RuntimeException{}public static class IdempotencyConflict extends RuntimeException{}public static class Insufficient extends RuntimeException{}}
